//! Embedding columns kept current (PLAN.md §M14.22 E4b): `GENERATED BY
//! EMBEDDING (expr) USING m`, the queue, the rounds, retries and the
//! circuit, pending rows (`embedding.pending`), a writer racing a round,
//! a column moving to another model (E5), and crashes on the simulation.

use std::path::Path;
use std::sync::atomic::{AtomicBool, AtomicU64, AtomicUsize, Ordering};
use std::sync::{Arc, Mutex};
use std::time::Duration;

use nucleus_kv::{Database, Kv, Options, TxnOptions};
use nucleus_platform::harness;
use nucleus_platform::sim::{CrashMode, Faults, SimPlatform};
use nucleus_platform::{Rng, SplitMix64};
use nucleus_sql::error::{Error, Result};
use nucleus_sql::ext::Registry;
use nucleus_sql::models::{self, ModelProvider, Request, Spec};
use nucleus_sql::{Output, Session, TxnStatus, Value, catalog};

/// A text's vector is its length in characters, then 1s (`dims`, 2 by
/// default).  Down: every call
/// fails with `58030` (and a Retry-After, when one is set); a text with
/// `BAD` in it is refused (`55000`), with the batch it is in.
struct Scripted {
    name: &'static str,
    down: AtomicBool,
    retry_after_ms: AtomicU64,
    calls: AtomicUsize,
    texts: AtomicUsize,
    /// Run during the next call (a writer racing the round).
    during: Mutex<Option<Box<dyn FnOnce() + Send>>>,
}

impl Scripted {
    fn new(name: &'static str) -> Arc<Self> {
        let p = Arc::new(Scripted {
            name,
            down: AtomicBool::new(false),
            retry_after_ms: AtomicU64::new(0),
            calls: AtomicUsize::new(0),
            texts: AtomicUsize::new(0),
            during: Mutex::new(None),
        });
        models::register(p.clone()).unwrap();
        p
    }

    fn calls(&self) -> usize {
        self.calls.load(Ordering::SeqCst)
    }
}

impl ModelProvider for Scripted {
    fn name(&self) -> &str {
        self.name
    }

    fn define(&self, o: &models::Options, _files: &models::Files<'_>) -> Result<Spec> {
        o.only(self.name, &["batch", "dims"])?;
        Ok(Spec {
            dimensions: o.number("dims", 2..=16)?.unwrap_or(2) as u32,
            max_batch: o.number("batch", 1..=1000)?.unwrap_or(1000) as usize,
        })
    }

    fn embed(&self, r: &Request<'_>) -> Result<Vec<Vec<f32>>> {
        self.calls.fetch_add(1, Ordering::SeqCst);
        if let Some(f) = self.during.lock().unwrap().take() {
            f();
        }
        if self.down.load(Ordering::SeqCst) {
            let e = Error::io(format!("{} is down", self.name));
            return Err(match self.retry_after_ms.load(Ordering::SeqCst) {
                0 => e,
                ms => e.with_hint(models::retry_hint(Duration::from_millis(ms))),
            });
        }
        if r.texts.iter().any(|t| t.contains("BAD")) {
            return Err(Error::prerequisite("the provider refused a text"));
        }
        self.texts.fetch_add(r.texts.len(), Ordering::SeqCst);
        Ok(r.texts
            .iter()
            .map(|t| {
                let mut v = vec![1.0; r.dimensions as usize];
                v[0] = t.chars().count() as f32;
                v
            })
            .collect())
    }

    fn remote(&self) -> bool {
        false
    }
}

fn open(p: &Arc<SimPlatform>) -> nucleus_kv::Result<Database> {
    Database::open_on(p.clone(), Path::new("/db"), Options::default())
}

fn db(seed: u64) -> (Arc<SimPlatform>, Arc<dyn Kv>) {
    let p = Arc::new(SimPlatform::new(seed));
    let kv: Arc<dyn Kv> = Arc::new(open(&p).unwrap());
    (p, kv)
}

fn rows(s: &mut Session, sql: &str) -> Vec<Vec<Value>> {
    match s.execute(sql).unwrap().pop().unwrap() {
        Output::Rows { rows, .. } => rows,
        other => panic!("{other:?}"),
    }
}

fn texts(s: &mut Session, sql: &str) -> Vec<String> {
    rows(s, sql)
        .into_iter()
        .map(|r| r.iter().map(|v| v.render()).collect::<Vec<_>>().join(" "))
        .collect()
}

fn code(s: &mut Session, sql: &str) -> String {
    s.execute(sql).unwrap_err().code.to_string()
}

#[test]
fn columns_are_kept_current() {
    let p = Scripted::new("scripted_current");
    let (_, kv) = db(1);
    let mut s = Session::new(kv);
    s.execute("CREATE MODEL m USING scripted_current").unwrap();
    s.execute(
        "CREATE TABLE docs (id int PRIMARY KEY, title text, body text, n int, \
         v vector GENERATED BY EMBEDDING (title || ' ' || body) USING m)",
    )
    .unwrap();
    // The type takes the model's dimensions.
    assert_eq!(
        texts(
            &mut s,
            "SELECT type, generated, generation_expr, model FROM nc_catalog.columns \
             WHERE table_name = 'docs' AND name = 'v'"
        ),
        vec!["vector(2) embedding title || ' ' || body m"]
    );
    s.execute(
        "INSERT INTO docs (id, title, body, n) VALUES (1, 'ab', 'cde', 0), (2, 'x', NULL, 0)",
    )
    .unwrap();
    // The statement's round made them: one text (the other's is NULL).
    assert_eq!(
        texts(&mut s, "SELECT id, v FROM docs ORDER BY id"),
        vec!["1 [6,1]", "2 NULL"]
    );
    assert_eq!((p.calls(), p.texts.load(Ordering::SeqCst)), (1, 1));
    // A column the text is not made of: no job.
    s.execute("UPDATE docs SET n = 5").unwrap();
    assert_eq!(p.calls(), 1);
    // One it is: the new text's vector.
    s.execute("UPDATE docs SET body = 'cdefgh' WHERE id = 1")
        .unwrap();
    assert_eq!(
        texts(&mut s, "SELECT v FROM docs WHERE id = 1"),
        vec!["[9,1]"]
    );
    assert_eq!(p.calls(), 2);
    // A key changed: the vector goes with the row.
    s.execute("UPDATE docs SET id = 10 WHERE id = 1").unwrap();
    assert_eq!(
        texts(&mut s, "SELECT v FROM docs WHERE id = 10"),
        vec!["[9,1]"]
    );
    assert_eq!(p.calls(), 2);
    s.execute("UPDATE docs SET body = 'y' WHERE id = 2")
        .unwrap();
    assert_eq!(
        texts(&mut s, "SELECT v FROM docs WHERE id = 2"),
        vec!["[3,1]"]
    );
    assert_eq!(
        texts(&mut s, "SELECT count(*) FROM nc_catalog.embedding_jobs"),
        vec!["0"]
    );
    // The same text twice is embedded once (the models' cache).
    s.execute("INSERT INTO docs (id, title, body, n) VALUES (3, 'x', 'y', 0)")
        .unwrap();
    assert_eq!(
        texts(&mut s, "SELECT v FROM docs WHERE id = 3"),
        vec!["[3,1]"]
    );
    assert_eq!(p.calls(), 3);

    // Made, not given.
    assert_eq!(
        code(&mut s, "INSERT INTO docs (id, v) VALUES (4, '[1,1]')"),
        "428C9"
    );
    assert_eq!(code(&mut s, "UPDATE docs SET v = NULL"), "428C9");
    // What an embedding column needs.
    for (sql, c) in [
        (
            "CREATE TABLE b (t text, v vector GENERATED BY EMBEDDING (t) USING m)",
            "42P17",
        ),
        (
            "CREATE TABLE b (id int PRIMARY KEY, t text, v vector NOT NULL GENERATED BY EMBEDDING (t) USING m)",
            "42P17",
        ),
        (
            "CREATE TABLE b (id int PRIMARY KEY, t text, v vector(3) GENERATED BY EMBEDDING (t) USING m)",
            "42804",
        ),
        (
            "CREATE TABLE b (id int PRIMARY KEY, t text, v int GENERATED BY EMBEDDING (t) USING m)",
            "42804",
        ),
        (
            "CREATE TABLE b (id int PRIMARY KEY, t text, v vector GENERATED BY EMBEDDING (t) USING nope)",
            "42704",
        ),
        (
            "CREATE TABLE b (id int PRIMARY KEY, t text, v vector GENERATED BY EMBEDDING (t) USING m, \
             w vector GENERATED BY EMBEDDING (v::text) USING m)",
            "42P17",
        ),
    ] {
        assert_eq!(code(&mut s, sql), c, "{sql}");
    }
    // A model in use stays.
    assert_eq!(code(&mut s, "DROP MODEL m"), "2BP01");
    // Added to a table with rows: each row's vector made.
    s.execute("ALTER TABLE docs ADD COLUMN w vector GENERATED BY EMBEDDING (body) USING m")
        .unwrap();
    assert_eq!(
        texts(&mut s, "SELECT id, w FROM docs ORDER BY id"),
        vec!["2 [1,1]", "3 [1,1]", "10 [6,1]"]
    );
    // A search over them.
    s.execute("CREATE INDEX docs_v ON docs USING hnsw (v)")
        .unwrap();
    assert_eq!(
        texts(&mut s, "SELECT id FROM docs ORDER BY v <-> '[9,1]' LIMIT 1"),
        vec!["10"]
    );
    // A query's vector by the column's own model: `embed(q)` beside it.
    assert_eq!(
        texts(
            &mut s,
            "SELECT id FROM docs ORDER BY embed('abcdefghi') <=> v LIMIT 1"
        ),
        vec!["10"]
    );
    assert_eq!(
        texts(
            &mut s,
            "SELECT id FROM docs ORDER BY v <=> embed('abcdefghi') LIMIT 1"
        ),
        vec!["10"]
    );
    // Deleted rows and a dropped table take their jobs.
    p.down.store(true, Ordering::SeqCst);
    s.execute("INSERT INTO docs (id, title, body) VALUES (20, 'a', 'b')")
        .unwrap();
    assert_eq!(
        texts(&mut s, "SELECT count(*) FROM nc_catalog.embedding_jobs"),
        vec!["2"]
    );
    s.execute("DELETE FROM docs WHERE id = 20").unwrap();
    assert_eq!(
        texts(&mut s, "SELECT count(*) FROM nc_catalog.embedding_jobs"),
        vec!["0"]
    );
    s.execute("INSERT INTO docs (id, title, body) VALUES (21, 'a', 'b')")
        .unwrap();
    s.execute("DROP TABLE docs").unwrap();
    assert_eq!(
        texts(&mut s, "SELECT count(*) FROM nc_catalog.embedding_jobs"),
        vec!["0"]
    );
    s.execute("DROP MODEL m").unwrap();
}

#[test]
fn outages_are_retried_and_pending_rows_chosen() {
    let p = Scripted::new("scripted_outage");
    let (sim, kv) = db(2);
    let mut s = Session::new(kv.clone());
    s.execute("CREATE MODEL m USING scripted_outage WITH (batch = 2)")
        .unwrap();
    s.execute(
        "CREATE TABLE docs (id int PRIMARY KEY, body text, \
         v vector GENERATED BY EMBEDDING (body) USING m)",
    )
    .unwrap();
    s.execute("INSERT INTO docs VALUES (1, 'ready')").unwrap();
    p.down.store(true, Ordering::SeqCst);
    s.execute("INSERT INTO docs VALUES (2, 'later')").unwrap();
    assert_eq!(
        texts(
            &mut s,
            "SELECT table_name, column_name, model, key, state, attempts, error \
             FROM nc_catalog.embedding_jobs"
        ),
        vec!["docs v m 2 retrying 1 scripted_outage is down (58030)"]
    );
    // Pending rows: as they are, left out, or waited for.
    assert_eq!(
        texts(&mut s, "SELECT id, v FROM docs ORDER BY id"),
        vec!["1 [5,1]", "2 NULL"]
    );
    s.execute("SET embedding.pending = skip").unwrap();
    assert_eq!(texts(&mut s, "SELECT id FROM docs ORDER BY id"), vec!["1"]);
    assert_eq!(
        texts(
            &mut s,
            "SELECT count(*) FROM docs d JOIN docs e ON d.id = e.id"
        ),
        vec!["1"]
    );
    assert_eq!(code(&mut s, "SET embedding.pending = sometimes"), "22023");

    // Backoff: the next call after the wait (at most 1 s for the first).
    let before = p.calls();
    s.execute("SELECT 1").unwrap();
    assert_eq!(p.calls(), before, "not before its time");
    sim.sim_clock().advance(Duration::from_secs(2));
    s.execute("SELECT 1").unwrap();
    assert_eq!(p.calls(), before + 1, "tried again");
    // Five failures in a row open the model's circuit: a new job waits.
    for _ in 0..3 {
        sim.sim_clock().advance(Duration::from_secs(600));
        s.execute("SELECT 1").unwrap();
    }
    assert_eq!(p.calls(), before + 4);
    s.execute("INSERT INTO docs VALUES (3, 'also')").unwrap();
    assert_eq!(p.calls(), before + 4, "the circuit is open");
    sim.sim_clock().advance(Duration::from_secs(31));
    s.execute("SELECT 1").unwrap();
    assert_eq!(
        p.calls(),
        before + 5,
        "one call when it has been open long enough"
    );
    // The provider's Retry-After is obeyed.
    p.retry_after_ms.store(7_000, Ordering::SeqCst);
    sim.sim_clock().advance(Duration::from_secs(600));
    s.execute("SELECT 1").unwrap();
    let after = p.calls();
    sim.sim_clock().advance(Duration::from_secs(6));
    s.execute("SELECT 1").unwrap();
    assert_eq!(p.calls(), after);
    sim.sim_clock().advance(Duration::from_secs(2));
    s.execute("SELECT 1").unwrap();
    assert!(p.calls() > after);

    // Waiting: past the statement's time, an error; …
    s.execute("SET embedding.pending = wait").unwrap();
    s.execute("SET statement_timeout = '5s'").unwrap();
    assert_eq!(code(&mut s, "SELECT id FROM docs"), "57014");
    // … in a transaction that has its snapshot, refused; …
    s.execute("SET embedding.pending = include").unwrap();
    s.execute("BEGIN").unwrap();
    s.execute("SELECT 1").unwrap();
    s.execute("SET embedding.pending = wait").unwrap();
    assert_eq!(code(&mut s, "SELECT id FROM docs"), "25001");
    s.execute("ROLLBACK").unwrap();
    // … and once the provider is back, the rows' vectors (the simulated
    // time passes while it waits).
    p.down.store(false, Ordering::SeqCst);
    s.execute("SET statement_timeout = '1h'").unwrap();
    assert_eq!(
        texts(&mut s, "SELECT id, v FROM docs ORDER BY id"),
        vec!["1 [5,1]", "2 [5,1]", "3 [4,1]"]
    );
    assert_eq!(
        texts(&mut s, "SELECT count(*) FROM nc_catalog.embedding_jobs"),
        vec!["0"]
    );

    // A text the model refuses fails alone, at once, and is retried when
    // its row changes.
    s.execute("SET embedding.pending = include").unwrap();
    s.execute("INSERT INTO docs VALUES (4, 'fine'), (5, 'a BAD one'), (6, 'good')")
        .unwrap();
    assert_eq!(
        texts(&mut s, "SELECT id, v FROM docs WHERE id >= 4 ORDER BY id"),
        vec!["4 [4,1]", "5 NULL", "6 [4,1]"]
    );
    assert_eq!(
        texts(
            &mut s,
            "SELECT key, state, attempts, error FROM nc_catalog.embedding_jobs"
        ),
        vec!["5 failed 1 the provider refused a text (55000)"]
    );
    // Failed for good does not hold up a wait.
    s.execute("SET embedding.pending = wait").unwrap();
    assert_eq!(texts(&mut s, "SELECT count(*) FROM docs"), vec!["6"]);
    s.execute("SET embedding.pending = include").unwrap();
    s.execute("UPDATE docs SET body = 'mended' WHERE id = 5")
        .unwrap();
    assert_eq!(
        texts(&mut s, "SELECT v FROM docs WHERE id = 5"),
        vec!["[6,1]"]
    );
}

#[test]
fn a_rate_limit_spaces_the_rounds() {
    let p = Scripted::new("scripted_limited");
    let (sim, kv) = db(4);
    let mut s = Session::new(kv.clone());
    s.execute("CREATE MODEL m USING scripted_limited WITH (batch = 1, requests_per_minute = 1)")
        .unwrap();
    s.execute(
        "CREATE TABLE docs (id int PRIMARY KEY, body text, \
         v vector GENERATED BY EMBEDDING (body) USING m)",
    )
    .unwrap();
    // One call a minute: the round makes the first and is told when to
    // come back for the second — not the provider down, so no circuit.
    s.execute("INSERT INTO docs VALUES (1, 'one'), (2, 'two')")
        .unwrap();
    assert_eq!(p.calls(), 1);
    assert_eq!(
        texts(
            &mut s,
            "SELECT key, state, error FROM nc_catalog.embedding_jobs ORDER BY key"
        ),
        vec![
            "1 retrying model \"m\" is at its rate limit (1 calls, any tokens a minute) (53400)",
            "2 retrying model \"m\" is at its rate limit (1 calls, any tokens a minute) (53400)"
        ]
    );
    for _ in 0..6 {
        sim.sim_clock().advance(Duration::from_secs(5));
        s.execute("SELECT 1").unwrap();
    }
    assert_eq!(p.calls(), 1, "not before the minute");
    sim.sim_clock().advance(Duration::from_secs(31));
    s.execute("SELECT 1").unwrap();
    // The first text's vector kept from the call made: one more call.
    assert_eq!(p.calls(), 2);
    assert_eq!(
        texts(&mut s, "SELECT id, v FROM docs ORDER BY id"),
        vec!["1 [3,1]", "2 [3,1]"]
    );
}

#[test]
fn a_writer_racing_a_round_wins() {
    let p = Scripted::new("scripted_race");
    let (_, kv) = db(3);
    let mut s = Session::new(kv.clone());
    s.execute("CREATE MODEL m USING scripted_race").unwrap();
    s.execute(
        "CREATE TABLE docs (id int PRIMARY KEY, body text, \
         v vector GENERATED BY EMBEDDING (body) USING m)",
    )
    .unwrap();
    // While the round's call is out, another session changes the text:
    // the round's vector (of the old text) must not land.
    let other = kv.clone();
    *p.during.lock().unwrap() = Some(Box::new(move || {
        let mut s = Session::new(other);
        s.execute("UPDATE docs SET body = 'a much longer text' WHERE id = 1")
            .unwrap();
    }));
    s.execute("INSERT INTO docs VALUES (1, 'short')").unwrap();
    // The newer text's job is the next round's.
    assert_eq!(
        texts(&mut s, "SELECT state FROM nc_catalog.embedding_jobs"),
        vec!["pending"]
    );
    assert_eq!(texts(&mut s, "SELECT v FROM docs"), vec!["[18,1]"]);
    assert_eq!(
        texts(&mut s, "SELECT count(*) FROM nc_catalog.embedding_jobs"),
        vec!["0"]
    );
    assert_eq!(p.calls(), 2);
}

#[test]
fn a_column_moves_to_another_model() {
    Scripted::new("scripted_move");
    let next = Scripted::new("scripted_move_next");
    let (sim, kv) = db(4);
    let mut s = Session::new(kv.clone());
    s.execute("CREATE MODEL m USING scripted_move").unwrap();
    s.execute("CREATE MODEL m3 USING scripted_move_next WITH (dims = 3, batch = 2)")
        .unwrap();
    s.execute(
        "CREATE TABLE docs (id int PRIMARY KEY, body text, \
         v vector GENERATED BY EMBEDDING (body) USING m)",
    )
    .unwrap();
    s.execute("CREATE INDEX docs_v ON docs USING hnsw (v)")
        .unwrap();
    s.execute("INSERT INTO docs VALUES (1, 'one'), (2, 'three'), (3, NULL)")
        .unwrap();
    assert_eq!(
        texts(&mut s, "SELECT id, v FROM docs ORDER BY id"),
        vec!["1 [3,1]", "2 [5,1]", "3 NULL"]
    );
    // Not an embedding column, no such model, no right to it.
    assert_eq!(
        code(&mut s, "ALTER TABLE docs ALTER COLUMN body SET MODEL m3"),
        "42809"
    );
    assert_eq!(
        code(&mut s, "ALTER TABLE docs ALTER COLUMN v SET MODEL nope"),
        "42704"
    );

    // The move: the next model's vectors made beside the column's, which
    // queries read until the last is made.
    next.down.store(true, Ordering::SeqCst);
    s.execute("ALTER TABLE docs ALTER COLUMN v SET MODEL m3")
        .unwrap();
    assert_eq!(
        texts(
            &mut s,
            "SELECT type, model, model_version, next_model FROM nc_catalog.columns \
             WHERE table_name = 'docs' AND name = 'v'"
        ),
        vec!["vector(2) m 0 m3"]
    );
    assert_eq!(
        texts(
            &mut s,
            "SELECT model, kind, key, state FROM nc_catalog.embedding_jobs ORDER BY key"
        ),
        vec!["m3 next 1 retrying", "m3 next 2 retrying"]
    );
    // The model being moved to is not dropped under the column.
    assert_eq!(code(&mut s, "DROP MODEL m3"), "2BP01");
    // (A NULL text needs no call: done at once.)  Writes during the move: the column's vector at once, the next
    // model's job beside it; a wait waits for the column's alone.
    s.execute("SET embedding.pending = wait").unwrap();
    s.execute("INSERT INTO docs VALUES (4, 'four')").unwrap();
    s.execute("UPDATE docs SET body = 'uno' WHERE id = 1")
        .unwrap();
    s.execute("UPDATE docs SET id = 20 WHERE id = 2").unwrap();
    s.execute("DELETE FROM docs WHERE id = 3").unwrap();
    assert_eq!(
        texts(&mut s, "SELECT id, v FROM docs ORDER BY id"),
        vec!["1 [3,1]", "4 [4,1]", "20 [5,1]"]
    );
    assert_eq!(
        texts(
            &mut s,
            "SELECT kind, key FROM nc_catalog.embedding_jobs ORDER BY key::int"
        ),
        vec!["next 1", "next 4", "next 20"]
    );
    assert_eq!(
        texts(&mut s, "SELECT id FROM docs ORDER BY v <-> '[4,1]' LIMIT 1"),
        vec!["4"]
    );
    // The model back: the rest made, and the column takes them at once —
    // its type, its index, its model and version.
    next.down.store(false, Ordering::SeqCst);
    sim.sim_clock().advance(Duration::from_secs(600));
    s.execute("SET embedding.pending = include").unwrap();
    s.execute("SELECT 1").unwrap();
    assert_eq!(
        texts(&mut s, "SELECT id, v FROM docs ORDER BY id"),
        vec!["1 [3,1,1]", "4 [4,1,1]", "20 [5,1,1]"]
    );
    assert_eq!(
        texts(
            &mut s,
            "SELECT type, model, model_version, next_model FROM nc_catalog.columns \
             WHERE table_name = 'docs' AND name = 'v'"
        ),
        vec!["vector(3) m3 1 NULL"]
    );
    assert_eq!(
        texts(&mut s, "SELECT count(*) FROM nc_catalog.embedding_jobs"),
        vec!["0"]
    );
    assert_eq!(
        texts(
            &mut s,
            "SELECT id FROM docs ORDER BY v <-> '[5,1,1]' LIMIT 1"
        ),
        vec!["20"]
    );
    s.execute("INSERT INTO docs VALUES (5, 'fiver')").unwrap();
    assert_eq!(
        texts(&mut s, "SELECT v FROM docs WHERE id = 5"),
        vec!["[5,1,1]"]
    );
    // The old model is free again.
    s.execute("CREATE TABLE keep (id int PRIMARY KEY)").unwrap();
    s.execute("DROP MODEL m").unwrap();

    // A move given up: SET MODEL to the column's own model.
    s.execute("CREATE MODEL m2 USING scripted_move_next WITH (dims = 3)")
        .unwrap();
    next.down.store(true, Ordering::SeqCst);
    s.execute("ALTER TABLE docs ALTER COLUMN v SET MODEL m2")
        .unwrap();
    assert_eq!(
        texts(&mut s, "SELECT count(*) FROM nc_catalog.embedding_jobs"),
        vec!["4"]
    );
    s.execute("ALTER TABLE docs ALTER COLUMN v SET MODEL m3")
        .unwrap();
    assert_eq!(
        texts(
            &mut s,
            "SELECT model, model_version, next_model FROM nc_catalog.columns \
             WHERE table_name = 'docs' AND name = 'v'"
        ),
        vec!["m3 1 NULL"]
    );
    assert_eq!(
        texts(&mut s, "SELECT count(*) FROM nc_catalog.embedding_jobs"),
        vec!["0"]
    );
    s.execute("DROP MODEL m2").unwrap();
    let txn = kv.begin(TxnOptions::read_only()).unwrap();
    let problems = nucleus_sql::check::check(&*txn, &Registry::builtin()).unwrap();
    assert_eq!(problems, Vec::<String>::new());
}

const STEPS: u64 = 30;

/// Step `i`'s SQL, or `None` for a round — by the seed alone.
fn step(rng: &SplitMix64, i: u64) -> Option<String> {
    let setup = [
        "CREATE MODEL m USING scripted_crash WITH (batch = 3)",
        "CREATE TABLE docs (id int PRIMARY KEY, body text, \
         v vector GENERATED BY EMBEDDING ('<' || body || '>') USING m)",
        "CREATE INDEX docs_v ON docs USING hnsw (v)",
        "CREATE MODEL m3 USING scripted_crash WITH (batch = 2, dims = 3)",
        "CREATE TABLE parts CHUNKS OF docs (body) BY tokens SIZE 5",
    ];
    if let Some(s) = setup.get(i as usize) {
        return Some(s.to_string());
    }
    let k = rng.below(40);
    let body = |rng: &SplitMix64| "x".repeat(1 + rng.below(30) as usize);
    Some(match rng.below(7) {
        0 | 1 => {
            let rows: Vec<String> = (0..=rng.below(5))
                .map(|j| format!("({}, '{}')", 100 + k * 10 + j, body(rng)))
                .collect();
            format!("INSERT INTO docs VALUES {}", rows.join(", "))
        }
        2 => format!(
            "UPDATE docs SET body = '{}' WHERE id % 7 = {}",
            body(rng),
            k % 7
        ),
        3 => format!("DELETE FROM docs WHERE id % 11 = {}", k % 11),
        4 => format!("UPDATE docs SET id = id + 1000 WHERE id = {}", 100 + k * 10),
        5 => format!(
            "ALTER TABLE docs ALTER COLUMN v SET MODEL {}",
            if k.is_multiple_of(2) { "m3" } else { "m" }
        ),
        _ => return None,
    })
}

/// The workload's steps, by the seed.
fn plan(seed: u64) -> Vec<Option<String>> {
    let rng = SplitMix64::new(seed);
    (0..STEPS).map(|i| step(&rng, i)).collect()
}

/// The rows and the queue.
fn dump(kv: &dyn Kv) -> String {
    let txn = kv.begin(TxnOptions::read_only()).unwrap();
    let mut out = String::new();
    for t in catalog::tables(&*txn).unwrap() {
        let prefix = t.index_prefix(0);
        let end = nucleus_kv::prefix_end(&prefix).unwrap();
        for e in txn
            .scan(
                std::ops::Bound::Included(&prefix),
                std::ops::Bound::Excluded(&end),
            )
            .unwrap()
        {
            out.push_str(&format!("{:?}\n", e.unwrap()));
        }
    }
    // The queue and the next models' vectors.
    let q = [0x00u8, 0x17];
    for e in txn
        .scan(
            std::ops::Bound::Included(&q[..]),
            std::ops::Bound::Excluded(&[0x00u8, 0x19][..]),
        )
        .unwrap()
    {
        out.push_str(&format!("job {:?}\n", e.unwrap().0));
    }
    out
}

/// The workload until it ends or the file system crashes: the state
/// after each step (if `record`), the steps finished, whether the crash
/// hit inside one.
fn workload(p: &Arc<SimPlatform>, seed: u64, record: bool) -> (Vec<String>, u64, bool) {
    let Ok(db) = open(p) else {
        return (Vec::new(), 0, false);
    };
    let kv: Arc<dyn Kv> = Arc::new(db);
    // The rounds are the steps', not the statements'.
    nucleus_sql::embedding::rounds_by_caller(kv.as_ref());
    let reg = Registry::builtin();
    let mut s = Session::new(kv.clone());
    let mut states = Vec::new();
    if record {
        states.push(dump(&*kv));
    }
    for (i, st) in plan(seed).into_iter().enumerate() {
        let i = i as u64;
        match st {
            Some(sql) => {
                if s.execute(&sql).is_err() && s.status() != TxnStatus::Idle {
                    let _ = s.execute("ROLLBACK");
                }
            }
            None => {
                let _ = nucleus_sql::embedding::work(&kv, &reg);
            }
        }
        if p.sim_fs().crash_count() > 0 {
            return (states, i, true);
        }
        if record {
            states.push(dump(&*kv));
        }
    }
    (states, STEPS, false)
}

/// Every row's vector is its text's by the column's model, no job is
/// left, and no move under way.
fn all_current(kv: &Arc<dyn Kv>, ctx: &str) {
    let reg = Registry::builtin();
    loop {
        let r = nucleus_sql::embedding::work(kv, &reg).unwrap();
        if !r.worked() && r.due == 0 {
            break;
        }
    }
    let mut s = Session::new(kv.clone());
    s.execute("SET embedding.pending = wait").unwrap();
    let model = texts(
        &mut s,
        "SELECT model, next_model FROM nc_catalog.columns WHERE name = 'v'",
    );
    let ones = match model[0].as_str() {
        "m NULL" => ",1",
        "m3 NULL" => ",1,1",
        other => panic!("{ctx}: {other}"),
    };
    for r in texts(&mut s, "SELECT length(body) + 2, v FROM docs") {
        let (n, v) = r.split_once(' ').unwrap();
        assert_eq!(v, format!("[{n}{ones}]"), "{ctx}");
    }
    assert_eq!(
        texts(&mut s, "SELECT count(*) FROM nc_catalog.embedding_jobs"),
        vec!["0"],
        "{ctx}"
    );
    // Each document's one chunk is its text (a word of x's).
    if !texts(
        &mut s,
        "SELECT name FROM nc_catalog.tables WHERE name = 'parts'",
    )
    .is_empty()
    {
        assert_eq!(
            texts(
                &mut s,
                "SELECT (SELECT count(*) FROM docs), count(*), \
                 coalesce(sum(CASE WHEN p.chunk = d.body AND p.position = 1 THEN 1 ELSE 0 END), 0) \
                 FROM parts p JOIN docs d ON d.id = p.id"
            ),
            {
                let n = texts(&mut s, "SELECT count(*) FROM docs")[0].clone();
                vec![format!("{n} {n} {n}")]
            },
            "{ctx}"
        );
    }
    let txn = kv.begin(TxnOptions::read_only()).unwrap();
    let problems = nucleus_sql::check::check(&*txn, &Registry::builtin()).unwrap();
    assert_eq!(problems, Vec::<String>::new(), "{ctx}");
}

#[test]
fn embedding_columns_survive_a_crash_at_any_io_point() {
    Scripted::new("scripted_crash");
    for mode in [CrashMode::DropUnsynced, CrashMode::Torn] {
        harness::run("embedding_crash_at_any_io_point", 1, |seed| {
            let dry = Arc::new(SimPlatform::new(seed));
            let (states, done, _) = workload(&dry, seed, true);
            assert_eq!(done, STEPS);
            let total = dry.sim_fs().op_count();
            let kv: Arc<dyn Kv> = Arc::new(open(&dry).unwrap());
            all_current(&kv, "the dry run");
            let stride = (total / 150).max(1);
            let mut crashed = 0;
            for n in (1..=total).step_by(stride as usize) {
                let p = Arc::new(SimPlatform::new(seed));
                p.sim_fs().set_faults(Faults {
                    crash_mode: mode,
                    ..Faults::default()
                });
                p.sim_fs().crash_after_ops(n);
                let (_, done, in_step) = workload(&p, seed, false);
                if p.sim_fs().crash_count() == 0 {
                    continue;
                }
                crashed += 1;
                let ctx = format!("seed {seed:#x}, {mode:?} crash at op {n} (step {done})");
                let db = open(&p).unwrap_or_else(|e| panic!("{ctx}: reopen failed: {e}"));
                let kv: Arc<dyn Kv> = Arc::new(db);
                let got = dump(&*kv);
                let done = done as usize;
                // A statement is one transaction: the state before it or
                // after.  A round commits one a group of jobs and one a
                // column it moves to its next model: a crash inside may
                // leave any of their states — `all_current` below and the
                // check judge those.
                let round = plan(seed)[done].is_none();
                let ok = got == states[done]
                    || (in_step && (round || states.get(done + 1) == Some(&got)));
                assert!(
                    ok,
                    "{ctx}: recovered a state that no step left ({:?})",
                    plan(seed)[done]
                );
                if done >= 2 {
                    // The jobs the crash left are done after it.
                    all_current(&kv, &ctx);
                }
            }
            let runs = total.div_ceil(stride);
            eprintln!("{mode:?}: {runs} runs, {crashed} crashed");
            assert!(crashed * 10 >= runs * 9, "{crashed} of {runs} runs crashed");
        });
    }
}
